import org.apache.commons.math.linear.SingularValueDecompositionImpl;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for SingularValueDecompositionImpl.getU()
 * Aiming for high branch and line coverage.
 */
public class SingularValueDecompositionImpl_getU_TriageGen0Test {





    /**
     * Tests a square matrix case specifically to ensure the logic handles m == n correctly.
     */
    @Test
    public void testGetU_SquareMatrix() throws Exception {
        double[][] data = {
            {2.0, 0.0},
            {0.0, 2.0}
        };
        RealMatrix matrix = new Array2DRowRealMatrix(data);

        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u = svd.getU();
        assertNotNull(u);
        // For a diagonal matrix, U is identity
        assert(Math.abs(u.getEntry(0, 0) - 1.0) < 1e-9);
        assert(Math.abs(u.getEntry(1, 1) - 1.0) < 1e-9);
    }


}

